-- =====================================================================
-- CMS update 11: Recognition page content, editable Biography / News / Media page text.
--   * Fills in and publishes the Recognition page (only while it is still the untouched draft,
--     so edits your team has already made are never overwritten). The photos live in
--     public/site-images/recognition/ and can be replaced in Admin → Pages → Recognition.
--   * site_settings keys 'biography' and 'page_headers' become publicly readable.
-- Safe to run more than once.
-- =====================================================================
drop policy if exists "public reads settings" on public.site_settings;
create policy "public reads settings" on public.site_settings
  for select to anon, authenticated
  using (key in ('contact', 'socials', 'home', 'footer', 'images', 'achievements', 'header',
                 'biography', 'page_headers'));

update public.site_pages
set title = 'Recognition',
    eyebrow = 'About',
    intro = $txt$Senator Dr. Yunus Abiodun Akintunde’s service in public office has been shaped by dedication, results, and continuous learning. Over the years, his contributions to public administration, legislative development, and institutional leadership have earned him recognition through international invitations, honors, and academic engagements.$txt$,
    hero_image = '/site-images/recognition/06-ui75-ambassador.jpg',
    hero_alt = 'Senator Yunus Abiodun Akintunde, PhD holding his UI@75 Ambassador award',
    seo_description = 'Honours, international invitations and academic engagements of Senator Yunus Abiodun Akintunde, PhD, and his record of public service.',
    sections = $json$[{"type": "text", "heading": "Honours and engagements", "body": "He has demonstrated commendable leadership in his previous role as Chairman of the Senate Committee on Environment and currently serves as the pioneer chairman of the Senate Committee on the Southwest Development Commission. The committee is strategically positioned to strengthen regional cooperation, accelerate coordinated development, and improve the delivery of democratic dividends across the Southwest.\n\nHis legislative engagements also earned him a special invitation as the sole representative from Nigeria by the Government of the Republic of Korea to a distinguished parliamentary guests’ program held in Seoul, South Korea, from April 20 to 26, 2025.\n\nIn addition, Senator Akintunde was part of the Nigerian delegation to COP28 in Dubai, where he participated in discussions on the economic implications of climate change for African nations. Following his contribution and speech at the engagement, he received a decorative ambassadorial appointment.\n\nHis academic association with the University of Ibadan also earned him the honorary distinction of UI@75 Ambassador in November 2023.\n\nOn the intellectual front, he has received invitations to deliver lectures and participate in academic engagements at reputable institutions, including Ladoke Akintola University of Technology, the Federal University Oye-Ekiti, and the University of Uyo.\n\nThese recognitions reflect his commitment to effective representation, institutional strengthening, intellectual development, and the advancement of opportunities for the people he serves.", "image": "", "caption": "", "imageSide": "right"}, {"type": "list", "heading": "Public Service & Legislative Leadership", "intro": "", "items": ["Commissioner, Oyo State Civil Service Commission (1999–2003).", "Commissioner for Works and Transport, Oyo State (2011–2012).", "Executive Assistant to the Governor of Oyo State (2014–2015).", "Senator of the Federal Republic of Nigeria, representing Oyo Central Senatorial District (2023–Present).", "Pioneer Chairman, Senate Committee on Southwest Development Commission.", "Deputy Chairman, Senate Committee on Police Affairs."]}, {"type": "gallery", "heading": "Recognition in pictures", "images": [{"url": "/site-images/recognition/01-radio-nigeria-award.jpg", "caption": "Receiving Radio Nigeria’s Best-Performing Senator of the Year 2026 award from the FRCN Ibadan Zonal Station."}, {"url": "/site-images/recognition/02-radio-nigeria-certificate.jpg", "caption": "The Best-Performing Senator of the Year 2026 certificate, conferred by Radio Nigeria, Ibadan Zonal Station, on 2 November 2026."}, {"url": "/site-images/recognition/03-newspeak-award.jpg", "caption": "Receiving an award at the Newspeak & Associates 10th anniversary awards."}, {"url": "/site-images/recognition/04-newspeak-presentation.jpg", "caption": "The award presentation at the Newspeak & Associates 10th anniversary ceremony."}, {"url": "/site-images/recognition/05-fuoye-award.jpg", "caption": "Honoured with an award by the Federal University Oye-Ekiti (FUOYE)."}, {"url": "/site-images/recognition/06-ui75-ambassador.jpg", "caption": "UI@75 Ambassador honour from the University of Ibadan."}, {"url": "/site-images/recognition/07-ui75-ambassador-with-ui.jpg", "caption": "With a University of Ibadan representative after receiving the UI@75 Ambassador award."}, {"url": "/site-images/recognition/08-ui75-national-assembly.jpg", "caption": "UI@75 Ambassador awards presented at the National Assembly."}, {"url": "/site-images/recognition/09-surveying-fellowship.jpg", "caption": "Honorary Fellowship Award from the School of Surveying, presented at the school’s convocation."}, {"url": "/site-images/recognition/10-senate-chamber.jpg", "caption": "In the Senate chamber."}, {"url": "/site-images/recognition/11-national-assembly-meeting.jpg", "caption": "At a meeting in the National Assembly."}, {"url": "/site-images/recognition/12-national-assembly-group.jpg", "caption": "With colleagues and guests at the National Assembly."}, {"url": "/site-images/recognition/13-senate-committee-sitting.jpg", "caption": "At a Senate committee sitting."}, {"url": "/site-images/recognition/14-senate-office.jpg", "caption": "In his office at the National Assembly."}]}]$json$::jsonb,
    status = 'published'
where slug = 'recognition'
  and status = 'draft'
  and intro like '[%';

-- If the page was deleted, create it.
insert into public.site_pages (slug, title, eyebrow, intro, hero_image, hero_alt, seo_description, sections, status)
select 'recognition', 'Recognition', 'About', $txt$Senator Dr. Yunus Abiodun Akintunde’s service in public office has been shaped by dedication, results, and continuous learning. Over the years, his contributions to public administration, legislative development, and institutional leadership have earned him recognition through international invitations, honors, and academic engagements.$txt$,
       '/site-images/recognition/06-ui75-ambassador.jpg',
       'Senator Yunus Abiodun Akintunde, PhD holding his UI@75 Ambassador award',
       'Honours, international invitations and academic engagements of Senator Yunus Abiodun Akintunde, PhD, and his record of public service.',
       $json$[{"type": "text", "heading": "Honours and engagements", "body": "He has demonstrated commendable leadership in his previous role as Chairman of the Senate Committee on Environment and currently serves as the pioneer chairman of the Senate Committee on the Southwest Development Commission. The committee is strategically positioned to strengthen regional cooperation, accelerate coordinated development, and improve the delivery of democratic dividends across the Southwest.\n\nHis legislative engagements also earned him a special invitation as the sole representative from Nigeria by the Government of the Republic of Korea to a distinguished parliamentary guests’ program held in Seoul, South Korea, from April 20 to 26, 2025.\n\nIn addition, Senator Akintunde was part of the Nigerian delegation to COP28 in Dubai, where he participated in discussions on the economic implications of climate change for African nations. Following his contribution and speech at the engagement, he received a decorative ambassadorial appointment.\n\nHis academic association with the University of Ibadan also earned him the honorary distinction of UI@75 Ambassador in November 2023.\n\nOn the intellectual front, he has received invitations to deliver lectures and participate in academic engagements at reputable institutions, including Ladoke Akintola University of Technology, the Federal University Oye-Ekiti, and the University of Uyo.\n\nThese recognitions reflect his commitment to effective representation, institutional strengthening, intellectual development, and the advancement of opportunities for the people he serves.", "image": "", "caption": "", "imageSide": "right"}, {"type": "list", "heading": "Public Service & Legislative Leadership", "intro": "", "items": ["Commissioner, Oyo State Civil Service Commission (1999–2003).", "Commissioner for Works and Transport, Oyo State (2011–2012).", "Executive Assistant to the Governor of Oyo State (2014–2015).", "Senator of the Federal Republic of Nigeria, representing Oyo Central Senatorial District (2023–Present).", "Pioneer Chairman, Senate Committee on Southwest Development Commission.", "Deputy Chairman, Senate Committee on Police Affairs."]}, {"type": "gallery", "heading": "Recognition in pictures", "images": [{"url": "/site-images/recognition/01-radio-nigeria-award.jpg", "caption": "Receiving Radio Nigeria’s Best-Performing Senator of the Year 2026 award from the FRCN Ibadan Zonal Station."}, {"url": "/site-images/recognition/02-radio-nigeria-certificate.jpg", "caption": "The Best-Performing Senator of the Year 2026 certificate, conferred by Radio Nigeria, Ibadan Zonal Station, on 2 November 2026."}, {"url": "/site-images/recognition/03-newspeak-award.jpg", "caption": "Receiving an award at the Newspeak & Associates 10th anniversary awards."}, {"url": "/site-images/recognition/04-newspeak-presentation.jpg", "caption": "The award presentation at the Newspeak & Associates 10th anniversary ceremony."}, {"url": "/site-images/recognition/05-fuoye-award.jpg", "caption": "Honoured with an award by the Federal University Oye-Ekiti (FUOYE)."}, {"url": "/site-images/recognition/06-ui75-ambassador.jpg", "caption": "UI@75 Ambassador honour from the University of Ibadan."}, {"url": "/site-images/recognition/07-ui75-ambassador-with-ui.jpg", "caption": "With a University of Ibadan representative after receiving the UI@75 Ambassador award."}, {"url": "/site-images/recognition/08-ui75-national-assembly.jpg", "caption": "UI@75 Ambassador awards presented at the National Assembly."}, {"url": "/site-images/recognition/09-surveying-fellowship.jpg", "caption": "Honorary Fellowship Award from the School of Surveying, presented at the school’s convocation."}, {"url": "/site-images/recognition/10-senate-chamber.jpg", "caption": "In the Senate chamber."}, {"url": "/site-images/recognition/11-national-assembly-meeting.jpg", "caption": "At a meeting in the National Assembly."}, {"url": "/site-images/recognition/12-national-assembly-group.jpg", "caption": "With colleagues and guests at the National Assembly."}, {"url": "/site-images/recognition/13-senate-committee-sitting.jpg", "caption": "At a Senate committee sitting."}, {"url": "/site-images/recognition/14-senate-office.jpg", "caption": "In his office at the National Assembly."}]}]$json$::jsonb, 'published'
where not exists (select 1 from public.site_pages where slug = 'recognition');